AnthropicStreamProviderAdapter.stream/this.anthropicService
      .streamMessage(
        {
          messages: chatMessages,
          tools: chatTools.length > 0 ? chatTools : undefined,
          model: modelConfig.underlyingModel ?? modelConfig.modelName,
          thinkingLevel,
          thinkingDisplay
        },
        {
          organizationId,
          agentId,
          skipTracing: true,
          operation: "chatStreamPipeline"
        },
        {
          onRequestId: (id) => {
            capturedRequestId = id;
          },
          onMessage: (token) => {
            if (!textBlockStarted) {
              textBlockStarted = true;
              if (thinkingBlockStarted) {
                thinkingBlockStarted = false;
                const durationMs =
                  thinkingStartTime !== null ? Date.now() - thinkingStartTime : undefined;
                thinkingStartTime = null;
                sessionReasoningDurationMs += durationMs ?? 0;
                push({
                  event: {
                    type: "thinking-end",
                    blockId: currentThinkingBlockId ?? "",
                    durationMs
                  }
                });
              }
              currentTextBlockId = `text-${crypto.randomUUID()}`;
              push({ event: { type: "text-start", blockId: currentTextBlockId } });
            }
            push({
              event: { type: "text-delta", blockId: currentTextBlockId ?? "", delta: token }
            });
          },
          onReasoning: (delta) => {
            if (!thinkingBlockStarted) {
              thinkingBlockStarted = true;
              thinkingStartTime = Date.now();
              currentThinkingBlockId = `thinking-${crypto.randomUUID()}`;
              push({
                event: { type: "thinking-start", blockId: currentThinkingBlockId }
              });
            }
            push({
              event: {
                type: "thinking-delta",
                blockId: currentThinkingBlockId ?? "",
                delta
              }
            });
          },
          onFunctionCall: (callName, _args, toolCallId) => {
            // Fires at Anthropic's content_block_start for tool_use blocks — name and id are
            // known immediately while args are still streaming via input_json_delta. Emitting
            // tool-input-start here lets the frontend show a pending chip before the args are
            // fully parsed. The tool-input-available event is still emitted post-stream from
            // .then(finalMessage) below with the fully parsed input.
            if (!callName || !toolCallId) return;

            if (textBlockStarted) {
              textBlockStarted = false;
              push({
                event: { type: "text-end", blockId: currentTextBlockId ?? "" }
              });
            }

            push({
              event: {
                type: "tool-input-start",
                blockId: `tool-${toolCallId}`,
                toolCallId,
                toolName: callName
              }
            });
          },
          onFunctionCallArgsDelta: (toolCallId, delta) => {
            push({
              event: { type: "tool-input-delta", blockId: `tool-${toolCallId}`, toolCallId, delta }
            });
          },
          onEnd: (_msg) => {
            // Final message handled in result processing below
          },
          onUsage: (u) => {
            capturedUsage = {
              promptTokens: u.promptTokens,
              completionTokens: u.completionTokens,
              totalTokens: u.promptTokens + u.completionTokens,
              cacheReadInputTokens: u.cacheReadInputTokens,
              cacheCreationInputTokens: u.cacheCreationInputTokens,
              cachedTokens: u.cacheReadInputTokens
            };
          },
          // Mid-stream snapshots keep capturedUsage populated so the abort/error
          // exits below can attach partial usage; the final onUsage overwrites
          // with the authoritative totals on clean completion.
          onUsageSnapshot: (u) => {
            capturedUsage = {
              promptTokens: u.promptTokens,
              completionTokens: u.completionTokens,
              totalTokens: u.promptTokens + u.completionTokens,
              cacheReadInputTokens: u.cacheReadInputTokens,
              cacheCreationInputTokens: u.cacheCreationInputTokens,
              cachedTokens: u.cacheReadInputTokens
            };
          },
          onError: (err) => {
            const error = err instanceof Error ? err : new Error(String(err));
            push({ error });
          },
          ...(this.telemetryService
            ? { onTelemetry: (event) => this.telemetryService?.track(event) }
            : {})
        },
        upstreamSignal ? { signal: upstreamSignal } : undefined
      )
      .then()#0

