      .then(({ message, stopReason, messageId, resolvedModelName }) => {
        if (thinkingBlockStarted) {
          thinkingBlockStarted = false;
          const durationMs =
            thinkingStartTime !== null ? Date.now() - thinkingStartTime : undefined;
          thinkingStartTime = null;
          sessionReasoningDurationMs += durationMs ?? 0;
          push({
            event: {
              type: "thinking-end",
              blockId: currentThinkingBlockId ?? "",
              durationMs
            }
          });
        }
        if (textBlockStarted) {
          textBlockStarted = false;
          push({ event: { type: "text-end", blockId: currentTextBlockId ?? "" } });
        }

        // After the call completes, yield tool-input-available events from the final result
        const toolCalls =
          "tool_calls" in message && Array.isArray(message.tool_calls) ? message.tool_calls : [];

        for (const tc of toolCalls) {
          if (tc.type === "function") {
            let parsedInput: Record<string, unknown>;
            try {
              parsedInput = JSON.parse(tc.function.arguments) as Record<string, unknown>;
            } catch {
              parsedInput = {};
            }
            push({
              event: {
                type: "tool-input-available",
                blockId: `tool-${tc.id}`,
                toolCallId: tc.id,
                toolName: tc.function.name,
                input: parsedInput
              }
            });
          }
        }

        const resolvedResponseId = messageId ?? crypto.randomUUID();
        push({
          event: {
            type: "message-end",
            usage: capturedUsage,
            ...(stopReason ? { finishReason: stopReason } : {}),
            responseId: resolvedResponseId,
            ...(resolvedModelName && { resolvedModelName }),
            ...(capturedRequestId && { providerRequestId: capturedRequestId }),
            totalReasoningDurationMs: sessionReasoningDurationMs
          }
        });
        push({ done: true });
      })
      .catch()#0

