      .map((connection) => {
        try {
          // Decrypt settings if encrypted
          const rawSettings = safeGetSettings(connection.settings);
          if (!rawSettings) {
            this.logger.debug(`[ListTeamsApps] Skipping connection ${connection.id} - no settings`);
