      const nodeData = node.data as DependentNodeData
      if (nodeData?.skipOutputFormat) return null
      if (initialNode?.parentId === node.id) {
        return {
          id: node.id,
          schema: nodeData?.outputFormatForChildren ?? { type: WorkflowDisplayType.UNKNOWN },
          label: nodeData?.iteratorName ?? "iteration",
          nodeType: node.type
        }
      }
      // Check if the node is a loop/doWhile node and if it's an ancestor of the current node
      if (
        (node.type === "loop" || node.type === "doWhile") &&
        nodeData?.iteratorName &&
        ancestorIds.has(node.id)
      ) {
        return {
          id: node.id,
          schema: nodeData?.outputFormatForChildren ?? { type: WorkflowDisplayType.UNKNOWN },
          label: nodeData.iteratorName,
          nodeType: node.type
        }
      }
      const resolvedSchema =
        node.type === NodeType.platformListenerTrigger
          ? getPlatformListenerTriggerOutputSchema(
              nodeData?.platformEventType,
              nodeData?.outputFormat
            )
          : node.type && DATA_BACKED_TRIGGER_TYPES.has(node.type)
            ? getTriggerOutputSchema(nodeData ?? {})
            : nodeData?.outputFormat
      return {
        id: node.id,
        schema: resolvedSchema ?? { type: WorkflowDisplayType.UNKNOWN },
        label: nodeData?.label ?? "",
        nodeType: node.type
      }
    })
